mapper.select:
SELECT t.id AS id, t.trade_id AS trade_id, t.pair_id AS pair_id, t.maker_order_id AS maker_order_id, t.taker_order_id AS taker_order_id, t.maker_user_id AS maker_user_id, t.taker_user_id AS taker_user_id, t.price AS price, t.qty AS qty, t.quote_amount AS quote_amount, t.maker_fee AS maker_fee, t.taker_fee AS taker_fee, t.is_buyer_maker AS buyer_maker, t.executed_at AS executed_at, mo.order_id AS maker_order_no, tk.order_id AS taker_order_no FROM trades t JOIN trading_pairs tp ON tp.id = t.pair_id JOIN orders mo ON mo.id = t.maker_order_id JOIN orders tk ON tk.id = t.taker_order_id WHERE (t.maker_user_id = #{userId} OR t.taker_user_id = #{userId})
AND t.pair_id = #{pairId}
AND (t.maker_order_id = #{orderPkId} OR t.taker_order_id = #{orderPkId})
AND t.executed_at >= #{startTime}
AND t.executed_at <= #{endTime}
AND t.id < #{beforeId}
ORDER BY t.id DESC LIMIT #{limit}

SELECT COUNT(*) FROM trades
WHERE maker_order_id = #{makerOrderId}
  AND taker_order_id = #{takerOrderId}
  AND price = #{price}
  AND qty = #{qty}
  AND executed_at = #{executedAt}
